class Solution {
    public int maxProfit(int[] prices) {
        int buy1 = Integer.MIN_VALUE, sell1 = 0;
        int buy2 = Integer.MIN_VALUE, sell2 = 0;
        for (int price : prices) {
            buy1 = Math.max(buy1, -price);
            sell1 = Math.max(sell1, buy1 + price);
            buy2 = Math.max(buy2, sell1 - price);
            sell2 = Math.max(sell2, buy2 + price);
        }
        return sell2;
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int n = prices.length;
        int[] left = new int[n];
        int[] right = new int[n];
        int minPrice = prices[0];
        for (int i = 1; i < n; i++) {
            minPrice = Math.min(minPrice, prices[i]);
            left[i] = Math.max(left[i - 1], prices[i] - minPrice);
        }
        int maxPrice = prices[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            maxPrice = Math.max(maxPrice, prices[i]);
            right[i] = Math.max(right[i + 1], maxPrice - prices[i]);
        }
        int best = 0;
        for (int i = 0; i < n; i++) {
            best = Math.max(best, left[i] + right[i]);
        }
        return best;
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int[] hold = new int[3];
        int[] cash = new int[3];
        java.util.Arrays.fill(hold, Integer.MIN_VALUE / 4);
        for (int price : prices) {
            for (int t = 1; t <= 2; t++) {
                hold[t] = Math.max(hold[t], cash[t - 1] - price);
                cash[t] = Math.max(cash[t], hold[t] + price);
            }
        }
        return cash[2];
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int n = prices.length;
        int[][] dp = new int[3][n];
        for (int t = 1; t <= 2; t++) {
            int bestPrevious = -prices[0];
            for (int day = 1; day < n; day++) {
                dp[t][day] = Math.max(dp[t][day - 1], prices[day] + bestPrevious);
                bestPrevious = Math.max(bestPrevious, dp[t - 1][day - 1] - prices[day]);
            }
        }
        return dp[2][n - 1];
    }
}
